import {PACKING_CASES,PACKING_PAGES,PACKING_PURPOSES,PACKING_UNITS,PACKING_KINDS,PACKING_HELP,PACKING_SUPPORT,PACKING_EXAMPLE,packingById} from './parcel-packing-content.mjs';
const object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
const keys=(x,required,optional=[])=>object(x)&&required.every(k=>Object.hasOwn(x,k))&&Object.keys(x).every(k=>required.includes(k)||optional.includes(k));
const clone=x=>x===undefined?undefined:JSON.parse(JSON.stringify(x));
const same=(a,b)=>a===b||(Array.isArray(a)&&Array.isArray(b)?a.length===b.length&&a.every((v,i)=>same(v,b[i])):object(a)&&object(b)&&Object.keys(a).length===Object.keys(b).length&&Object.keys(a).every(k=>Object.hasOwn(b,k)&&same(a[k],b[k])));
const integer=(n,min,max)=>Number.isSafeInteger(n)&&n>=min&&n<=max;
const numericDraft=x=>typeof x==='string'&&x.length<=24;
export function parsePackingNumber(text){if(!numericDraft(text)||!/^\d+$/.test(text.trim()))return null;const n=Number(text.trim());return integer(n,0,100)?n:null;}
function sourceValid(s,c){return keys(s,['id','title','purpose','total','capacity','modelRevision','objectUnit'])&&typeof s.title==='string'&&typeof s.purpose==='string'&&typeof s.objectUnit==='string'&&['id','total','capacity','modelRevision'].every(k=>same(s[k],c[k]));}
const supportValid=s=>object(s)&&s.visual===true&&Object.entries(s).every(([k,v])=>PACKING_SUPPORT.includes(k)&&v===true);
const contextSupport=(d,s)=>(d.exampleStep===null||s.workedExample===true)&&(d.helpTopic===null||(d.helpTopic==='example'?s.workedExample===true&&d.exampleStep!==null:s[d.helpTopic]===true));
const containsSupport=(current,earlier)=>Object.keys(earlier).every(k=>current[k]===true);
const responseValid=r=>keys(r,['text','unit'])&&numericDraft(r.text)&&(r.unit===null||PACKING_UNITS.includes(r.unit));
const responseMapValid=(m,names)=>keys(m,names)&&names.every(k=>responseValid(m[k]));
const bagsValid=(bags,c)=>Array.isArray(bags)&&bags.length===8&&bags.every(n=>integer(n,0,c.capacity))&&bags.reduce((a,b)=>a+b,0)<=c.total;
const DRAFT_FIELDS=['bags','selectedBag','purpose','readings','answers','helpTopic','exampleStep'];
const draft=w=>Object.fromEntries(DRAFT_FIELDS.map(k=>[k,clone(w[k])]));
function draftValid(d,c){return keys(d,DRAFT_FIELDS)&&bagsValid(d.bags,c)&&integer(d.selectedBag,0,7)&&PACKING_PURPOSES.includes(d.purpose)&&responseMapValid(d.readings,['full','loose'])&&responseMapValid(d.answers,PACKING_PURPOSES)&&(d.helpTopic===null||PACKING_HELP.includes(d.helpTopic))&&(d.exampleStep===null||integer(d.exampleStep,0,3));}
export function packingModel(c,bags){const packed=bags.reduce((a,b)=>a+b,0);return {bags:clone(bags),packed,loose:c.total-packed,fullBags:bags.filter(n=>n===c.capacity).length,partialBags:bags.filter(n=>n>0&&n<c.capacity).length,loadedBags:bags.filter(n=>n>0).length};}
export function packingTargets(c){return {kits:Math.floor(c.total/c.capacity),remainder:c.total%c.capacity,all:Math.ceil(c.total/c.capacity)};}
const response=(d,kind)=>kind==='read-full'?d.readings.full:kind==='read-loose'?d.readings.loose:d.answers[kind];
const targetUnit=kind=>kind==='read-full'||kind==='kits'?'full bags':kind==='read-loose'?'loose envelopes':'loaded trips';
export function packingAssessment(c,d,kind){const m=packingModel(c,d.bags),t=packingTargets(c),r=response(d,kind),number=parsePackingNumber(r.text),reading=kind.startsWith('read-'),target=kind==='read-full'?m.fullBags:kind==='read-loose'?m.loose:t[kind];const numberMatches=number!==null&&number===target,unitMatches=r.unit===targetUnit(kind);const carriesAll=m.loose===0,minimalTrips=m.loadedBags===t.all,kitsReady=m.fullBags===t.kits&&m.partialBags===0&&m.loose===t.remainder,planReady=reading?null:kind==='kits'?kitsReady:carriesAll&&minimalTrips;return {number,target,expectedUnit:targetUnit(kind),valid:number!==null,numberMatches,unitMatches,matches:numberMatches&&unitMatches,...(reading?{}:{planReady,carriesAll,minimalTrips,fullBags:m.fullBags,partialBags:m.partialBags,loadedBags:m.loadedBags,loose:m.loose,ready:numberMatches&&unitMatches&&planReady})};}
const checkTarget=(c,d,kind)=>({number:packingAssessment(c,d,kind).target,unit:targetUnit(kind)});
const feedbackKey=kind=>({'read-full':'readFullFeedback','read-loose':'readLooseFeedback',kits:'kitsFeedback',all:'allFeedback'})[kind];
const latest=(w,kind)=>w.checks.findLast(s=>s.kind===kind)||null;
function checkValid(s,c){return keys(s,['kind','source','input','target','assessment','support','previouslyChecked','practice','modelVisible'])&&PACKING_KINDS.includes(s.kind)&&sourceValid(s.source,c)&&draftValid(s.input,c)&&supportValid(s.support)&&contextSupport(s.input,s.support)&&parsePackingNumber(response(s.input,s.kind).text)!==null&&same(s.target,checkTarget(c,s.input,s.kind))&&same(s.assessment,packingAssessment(c,s.input,s.kind))&&typeof s.previouslyChecked==='boolean'&&s.practice===true&&s.modelVisible===true;}
function artifact(c,w){return {source:clone(w.source),input:draft(w),target:checkTarget(c,w,w.purpose),assessment:packingAssessment(c,w,w.purpose),support:clone(w.support),practice:true,modelVisible:true};}
function artifactValid(s,c){return keys(s,['source','input','target','assessment','support','practice','modelVisible'])&&sourceValid(s.source,c)&&draftValid(s.input,c)&&supportValid(s.support)&&contextSupport(s.input,s.support)&&same(s.target,checkTarget(c,s.input,s.input.purpose))&&same(s.assessment,packingAssessment(c,s.input,s.input.purpose))&&s.practice===true&&s.modelVisible===true;}
// Current feedback depends on its own response and actual bags, never unrelated
// raw drafts or help navigation. Purpose checks additionally retain their context.
function matchesCurrent(w,s,kind){return !!s&&same(w.bags,s.input.bags)&&same(response(w,kind),response(s.input,kind))&&(!PACKING_PURPOSES.includes(kind)||w.purpose===s.input.purpose);}
function workValid(w,c){return keys(w,['source',...DRAFT_FIELDS,'support','checkedKinds','feedback','inputError','checks','kept','sealed'])&&sourceValid(w.source,c)&&draftValid(draft(w),c)&&supportValid(w.support)&&contextSupport(w,w.support)&&keys(w.checkedKinds,PACKING_KINDS)&&PACKING_KINDS.every(k=>typeof w.checkedKinds[k]==='boolean')&&keys(w.feedback,PACKING_KINDS)&&PACKING_KINDS.every(k=>typeof w.feedback[k]==='boolean')&&(w.inputError===null||PACKING_KINDS.includes(w.inputError)&&parsePackingNumber(response(w,w.inputError).text)===null&&!w.feedback[w.inputError])&&Array.isArray(w.checks)&&w.checks.length<=24&&w.checks.every(s=>checkValid(s,c)&&containsSupport(w.support,s.support)&&w.support[feedbackKey(s.kind)]===true)&&PACKING_KINDS.every(k=>(w.checkedKinds[k]===w.checks.some(s=>s.kind===k))&&(!w.feedback[k]||matchesCurrent(w,latest(w,k),k)))&&(w.kept===null||artifactValid(w.kept,c)&&containsSupport(w.support,w.kept.support))&&(w.sealed===null||artifactValid(w.sealed,c)&&containsSupport(w.support,w.sealed.support)&&w.sealed.assessment.ready);}
function valid(r){return keys(r,['version','currentCase','page','cases'],['recovered'])&&r.version===1&&PACKING_PAGES.includes(r.page)&&object(r.cases)&&Object.keys(r.cases).length<=4&&Object.entries(r.cases).every(([id,w])=>packingById(id)&&workValid(w,packingById(id)))&&(r.currentCase===null||packingById(r.currentCase)&&Object.hasOwn(r.cases,r.currentCase))&&(r.page==='choose'||r.currentCase!==null);}
const fresh=()=>({version:1,currentCase:null,page:'choose',cases:{}});
export function packingState(state){return !Object.hasOwn(state,'parcelPacking')?fresh():valid(state.parcelPacking)?state.parcelPacking:null;}
export function recoverPacking(state){if(!Object.hasOwn(state,'parcelPacking')||packingState(state))return false;state.parcelPacking={...fresh(),recovered:state.parcelPacking};return true;}
function change(state,fn){const r=packingState(state);if(!r)return false;const next=clone(r),result=fn(next);if(result===false||!valid(next))return false;state.parcelPacking=next;return result??true;}
const work=r=>r.currentCase?r.cases[r.currentCase]:null;
const flags=()=>Object.fromEntries(PACKING_KINDS.map(k=>[k,false]));
const blank=()=>({text:'',unit:null});
const newWork=c=>({source:clone(c),bags:Array(8).fill(0),selectedBag:0,purpose:'kits',readings:{full:blank(),loose:blank()},answers:{kits:blank(),all:blank()},helpTopic:null,exampleStep:null,support:{visual:true},checkedKinds:flags(),feedback:flags(),inputError:null,checks:[],kept:null,sealed:null});
function editWork(state,fn,{model=false,kind=null}={}){return change(state,r=>{const w=work(r);if(!w)return false;const result=fn(w,packingById(r.currentCase));if(result===false)return false;w.inputError=null;if(model)w.feedback=flags();else if(kind)w.feedback[kind]=false;return result;});}
export function choosePackingCase(state,id){const c=packingById(id);if(!c)return false;return change(state,r=>{if(!Object.hasOwn(r.cases,id))r.cases[id]=newWork(c);r.currentCase=id;r.page='pack';work(r).inputError=null;});}
export function setPackingPage(state,page){if(!PACKING_PAGES.includes(page))return false;return change(state,r=>{if(page!=='choose'&&!work(r))return false;r.page=page;if(work(r))work(r).inputError=null;});}
export function selectPackingBag(state,index){if(!integer(index,0,7))return false;return editWork(state,w=>{w.selectedBag=index;});}
export function movePackingEnvelope(state,delta){if(![-1,1].includes(delta))return false;return editWork(state,(w,c)=>{const n=w.bags[w.selectedBag]+delta;if(!integer(n,0,c.capacity)||delta===1&&packingModel(c,w.bags).loose===0)return false;w.bags[w.selectedBag]=n;w.support.handling=true;},{model:true});}
export function returnPackingBag(state){return editWork(state,w=>{if(!w.bags[w.selectedBag])return false;w.bags[w.selectedBag]=0;w.support.handling=true;},{model:true});}
export function clearPackingTable(state){return editWork(state,w=>{if(w.bags.every(n=>n===0))return false;w.bags=Array(8).fill(0);w.support.handling=true;},{model:true});}
export function fillPackingBagTogether(state){return editWork(state,(w,c)=>{const n=Math.min(c.capacity-w.bags[w.selectedBag],packingModel(c,w.bags).loose);if(!n)return false;w.support.countedFill=true;w.bags[w.selectedBag]+=n;},{model:true});}
export function setPackingPurpose(state,purpose){if(!PACKING_PURPOSES.includes(purpose))return false;return editWork(state,w=>{w.purpose=purpose;w.feedback.kits=false;w.feedback.all=false;});}
export function setPackingReading(state,kind,text){if(!['full','loose'].includes(kind)||!numericDraft(text))return false;return editWork(state,w=>{w.readings[kind].text=text;},{kind:'read-'+kind});}
export function setPackingReadingUnit(state,kind,unit){if(!['full','loose'].includes(kind)||unit!==null&&!PACKING_UNITS.includes(unit))return false;return editWork(state,w=>{w.readings[kind].unit=unit;},{kind:'read-'+kind});}
export function setPackingAnswer(state,purpose,text){if(!PACKING_PURPOSES.includes(purpose)||!numericDraft(text))return false;return editWork(state,w=>{w.answers[purpose].text=text;},{kind:purpose});}
export function setPackingAnswerUnit(state,purpose,unit){if(!PACKING_PURPOSES.includes(purpose)||unit!==null&&!PACKING_UNITS.includes(unit))return false;return editWork(state,w=>{w.answers[purpose].unit=unit;},{kind:purpose});}
export function checkPacking(state,kind){if(!PACKING_KINDS.includes(kind))return false;return change(state,r=>{const w=work(r),c=packingById(r.currentCase);if(!w||PACKING_PURPOSES.includes(kind)&&w.purpose!==kind)return false;if(parsePackingNumber(response(w,kind).text)===null){w.feedback[kind]=false;w.inputError=kind;return {valid:false,error:'Use a whole number from 0 to 100. A blank or malformed entry stays a draft.'};}const s={kind,source:clone(w.source),input:draft(w),target:checkTarget(c,w,kind),assessment:packingAssessment(c,w,kind),support:clone(w.support),previouslyChecked:w.checkedKinds[kind],practice:true,modelVisible:true};w.checks.push(s);if(w.checks.length>24){const redundant=w.checks.findIndex((s,i)=>w.checks.slice(i+1).some(t=>t.kind===s.kind));w.checks.splice(redundant,1);}w.checkedKinds[kind]=true;w.feedback[kind]=true;w.inputError=null;w.support[feedbackKey(kind)]=true;return clone(s);});}
export function setPackingHelp(state,topic){if(topic!==null&&!PACKING_HELP.includes(topic))return false;return editWork(state,w=>{w.helpTopic=topic;if(topic==='example'){w.support.workedExample=true;if(w.exampleStep===null)w.exampleStep=0;}else if(topic)w.support[topic]=true;});}
export function stepPackingExample(state,delta){if(![-1,1].includes(delta))return false;return editWork(state,w=>{const n=(w.exampleStep??0)+delta;if(!integer(n,0,3))return false;w.support.workedExample=true;w.exampleStep=n;});}
export function usePackingSupport(state,kind){if(!PACKING_SUPPORT.includes(kind)||['visual','handling','countedFill',...PACKING_KINDS.map(feedbackKey)].includes(kind))return false;return editWork(state,w=>{w.support[kind]=true;if(kind==='workedExample'&&w.exampleStep===null)w.exampleStep=0;});}
export function preparePackingTogether(state){return editWork(state,(w,c)=>{w.support.together=true;w.bags=Array(8).fill(0);const t=packingTargets(c);for(let i=0;i<t.kits;i++)w.bags[i]=c.capacity;if(w.purpose==='all'&&t.remainder)w.bags[t.kits]=t.remainder;w.answers[w.purpose]={text:String(t[w.purpose]),unit:targetUnit(w.purpose)};},{model:true});}
export function keepPacking(state){return change(state,r=>{const w=work(r);if(!w)return false;w.kept=artifact(packingById(r.currentCase),w);return clone(w.kept);});}
export function sealPacking(state){return change(state,r=>{const w=work(r),c=packingById(r.currentCase);if(!w||!packingAssessment(c,w,w.purpose).ready)return false;const s=artifact(c,w);if(w.sealed&&same(w.sealed,s))return false;w.sealed=s;return clone(s);});}
export function packingExample(step){if(!integer(step,0,3))return null;const bags=Array(8).fill(0);if(step>=1)bags[0]=4;if(step>=2){bags[1]=4;bags[2]=4;}if(step===3)bags[3]=2;return {...clone(PACKING_EXAMPLE),step,...packingModel(PACKING_EXAMPLE,bags)};}
export function packingView(state){const r=packingState(state);if(!r)return null;const w=work(r),c=packingById(r.currentCase);if(!w)return {case:null,work:null};const model=packingModel(c,w.bags),targets=packingTargets(c),latestChecks=Object.fromEntries(PACKING_KINDS.map(k=>[k,latest(w,k)])),assessment={readFull:packingAssessment(c,w,'read-full'),readLoose:packingAssessment(c,w,'read-loose'),kits:packingAssessment(c,w,'kits'),all:packingAssessment(c,w,'all')};assessment.ready=assessment[w.purpose].ready;return {case:c,work:w,model,targets,assessment,latestChecks,currentFeedback:Object.fromEntries(PACKING_KINDS.map(k=>[k,w.feedback[k]?latestChecks[k]:null])),inputError:w.inputError,keptEarlier:!!w.kept&&!same(w.kept,artifact(c,w)),sealedEarlier:!!w.sealed&&!same(w.sealed,artifact(c,w)),example:w.exampleStep===null?null:packingExample(w.exampleStep),actions:{add:{enabled:model.loose>0&&w.bags[w.selectedBag]<c.capacity},remove:{enabled:w.bags[w.selectedBag]>0},returnBag:{enabled:w.bags[w.selectedBag]>0},clear:{enabled:model.packed>0},fillTogether:{enabled:model.loose>0&&w.bags[w.selectedBag]<c.capacity},seal:{enabled:assessment.ready&&!(w.sealed&&same(w.sealed,artifact(c,w)))}}};}
